import sys; sys.path.insert(0, __import__("os").path.join(__import__("os").path.dirname(__file__), "..", "..", "pipeline"))
from scriptkit import sc, ch, save, S

# Grandma Ruth 117 · ANGLE: humiliated grandma + reveal (salesman mocks her; coffee can full of cash for her Marine grandson's truck)

sc("""Sweetheart, in December of two thousand twenty-one, my friend Helen walked into a fancy truck dealership in Florida, seventy-seven years old, in her gardening clothes, carrying an old coffee can under her arm. The top salesman looked her up and down and said, ma'am, the used lot is across the highway. Everybody laughed. He didn't know what was in that coffee can. Forty-six thousand dollars. Cash.""",
   "elderly woman carrying coffee can in car showroom", "THE USED LOT")
sc("""Tonight I'm going to tell you who that money was for, why Helen walked right past that salesman to the newest girl on the floor, and what happened to both of them by the end of the day. Stay with me, honey, because the look on that man's face is something Helen still describes to me on the phone every Christmas.""",
   "salesman shocked expression in showroom", "THE LOOK ON HIS FACE")

ch("Helen and Frank")
sc("""Helen and I grew up together in Mansfield, honey. She married a mechanic named Frank, the best mechanic in Richland County. He could fix anything with an engine. They never had much, but Frank saved. Every week, he put a few dollars into a red coffee can on the shelf in his garage. Every week for forty years. He never told anybody how much was in there, not even Helen.""",
   "red coffee can on garage shelf", "EVERY WEEK FOR FORTY YEARS")
sc("""When Frank retired, they moved to a little house in Florida, near Sarasota, close to their daughter, because Helen's knees couldn't take the Ohio winters anymore. Frank passed in two thousand twenty, in the spring. And when Helen was going through his garage that summer, she took down that red coffee can, and opened it, and sat down on an overturned bucket. It was packed, honey, tight, with rolled-up bills. And a note on top.""",
   "elderly woman sitting on bucket in garage", "PACKED WITH BILLS")
sc("""The note said, Helen. This is for Caleb's truck, when he comes home. Don't let anybody talk you out of it. Love, Frank. Caleb was their grandson, sweetheart. Frank's shadow. That boy had been in Frank's garage since he was four, handing him wrenches. And when he was eighteen, he joined the Marines. He was in Japan when his grandpa died. He couldn't come home for the funeral. In a minute I'll tell you why that truck mattered so much.""",
   "young Marine in dress uniform portrait", "FOR CALEB'S TRUCK")

ch("The promise")
sc("""When Caleb was twelve, honey, he and Frank used to sit on the tailgate of Frank's old pickup, eating sunflower seeds and watching the trucks go by on the highway. And Caleb would point at the new ones, the big shiny ones, and say, Grandpa, someday I'm going to have one of those. And Frank would say, when you come home from wherever life takes you, I'll buy you one. That's a promise.""",
   "grandfather and boy on pickup tailgate", "THAT'S A PROMISE")
sc("""Caleb was coming home on leave the week before Christmas, twenty twenty-one, his first time home since the funeral. And Helen was going to keep Frank's promise. She counted the money at the kitchen table three times. Forty-six thousand, two hundred dollars. And on December fifteenth, she put the coffee can in a grocery bag, got in her old Buick, and drove to the biggest truck dealership in town.""",
   "elderly woman counting cash at kitchen table", "$46,200")

sc("""Helen called me the night before, honey. She said, Ruth, I'm scared. I've never bought a car in my life. Frank did all that. What if they cheat me? And I said, Helen, you raised three children and buried a husband. You can buy a truck. Just remember what Frank always said. The one who listens is the one you buy from. She didn't know yet how right he was. I'll tell you how she found out in a minute.""",
   "elderly woman on phone at night worried", "THE ONE WHO LISTENS")
sc("""She barely slept that night, sweetheart. She kept getting up to check that the coffee can was still in the kitchen cabinet, behind the cereal boxes. At three in the morning, she sat at the table with Frank's photograph and said, out loud, Frank, I'm going to do it. I'm going to keep your promise. And she told me she could have sworn she smelled motor oil and sunflower seeds, just for a second.""",
   "elderly woman at kitchen table with photograph at night", "I'LL KEEP YOUR PROMISE")
ch("The showroom")
sc("""If you're enjoying Grandma's story, tap the like button for me, sweetheart. It helps more people find these stories. Helen had been out in her garden all morning, honey, and she didn't think to change. Old canvas pants with dirt on the knees, a faded sun hat, and Frank's old work shirt. She walked into that showroom, all glass and chrome and cold air conditioning, and she stood next to a big red truck and waited for somebody to help her.""",
   "elderly woman in gardening clothes in car showroom", "SHE WAITED")
sc("""There were four salesmen at the desks, honey. They all looked up. They all looked back down. She waited ten minutes. Then one of them finally walked over, a man about forty with slicked hair and a gold watch. His name tag said Brad. And before Helen could say a word, he said, ma'am, if you're looking for the restroom, it's in the back. And if you're looking for something in your budget, the used lot is across the highway.""",
   "slick salesman with gold watch smirking", "SOMETHING IN YOUR BUDGET")
sc("""And the other salesmen laughed, sweetheart. Helen said her face went hot as a stove. She said, I'm looking at this truck. And Brad said, that one's sixty-two thousand, ma'am. And he looked at her grocery bag, and he smiled, and he said, we don't take coupons. And he walked away, back to his desk, and picked up his phone. In a minute I'll tell you who came over next.""",
   "salesmen laughing at desks in showroom", "WE DON'T TAKE COUPONS")

ch("Maria")
sc("""A young woman came over from the back corner, honey. About twenty-six, in a black blazer that didn't quite fit, with a name tag that said Maria, and under it, in small letters, sales trainee. She'd been sitting at the desk nobody wanted, by the bathroom door. She said, ma'am, I'm sorry about that. Can I get you a glass of water? It's hot out there. Would you like to sit down?""",
   "young saleswoman offering glass of water", "PLEASE, SIT DOWN")
sc("""She sat Helen down in the air conditioning, honey, and brought her a cold water, and asked her what she was looking for. And Helen told her. About Frank, and the garage, and the tailgate, and the sunflower seeds, and the promise. And Maria listened to every word. She didn't look at her watch once. And when Helen got to the part about the funeral Caleb couldn't come home for, Maria's eyes filled up.""",
   "young woman listening to elderly woman at desk", "SHE JUST LISTENED")
sc("""Maria said, my brother's in the Navy. He missed our dad's funeral too. And then she said, Mrs. Helen, let's find Caleb the right truck. Not the most expensive one. The right one. And she spent two and a half hours with her, sweetheart. Showed her every truck on the lot. Explained everything in plain English. Took her on a test drive, with the windows down, so Helen could feel what Caleb would feel.""",
   "young woman and elderly woman on test drive", "THE RIGHT TRUCK")

ch("The coffee can")
sc("""So far, forty years of a red coffee can, a grandpa's promise, a salesman who laughed, and a trainee by the bathroom door. Helen picked a dark blue pickup, honey. Caleb's favorite color, and a lot like Frank's old truck, just new. It came to forty-four thousand eight hundred, out the door. And Maria said, how would you like to pay? Do you have financing? And Helen reached into her grocery bag. Stay with me.""",
   "dark blue pickup truck on dealership lot", "HOW WILL YOU PAY?")
sc("""She put that red coffee can on Maria's desk and took off the lid, honey. And she started pulling out rolls of bills, held with rubber bands, and stacking them on the desk. Twenties and fifties and hundreds, forty years of Frank's Fridays. Maria's mouth fell open. And across the showroom, Brad stopped talking on his phone. And the other salesmen stood up at their desks to look.""",
   "rolls of cash stacked on dealership desk", "FORTY YEARS OF FRIDAYS")
sc("""It took the finance manager forty minutes to count it all, sweetheart, twice, with a machine. And while he counted, Brad came over. He was all smiles now. He said, ma'am, I'm the senior sales associate here. Maria's still in training. Let me take care of the paperwork for you, to make sure everything's done right. And he put his hand on the folder. He wanted the commission, honey. On a sale he'd laughed at.""",
   "salesman reaching for folder on desk", "LET ME HANDLE IT")

ch("Helen's answer")
sc("""And Helen took her hand, her old gardening hand with dirt still under the nails, and she put it flat on top of that folder. And she said, young man, when I walked in that door, I had forty-six thousand dollars in a grocery bag. You saw an old woman in dirty pants. This young lady saw a person. She gets every penny. And the whole showroom heard it, because Helen has always had a voice that carries.""",
   "elderly hand flat on top of folder", "SHE SAW A PERSON")
sc("""Brad went red to the tips of his ears, sweetheart. He mumbled something and went back to his desk. And the general manager, who'd been watching from his glass office the whole time, came out and shook Helen's hand. And then he turned to Maria and said, nice work. Come see me in my office after this. Maria went white. She thought she was in trouble.""",
   "manager shaking hands with elderly woman", "COME SEE ME")

ch("Maria's secret")
sc("""She wasn't in trouble, honey. Helen found out later what Maria hadn't told her. It was her last week. She hadn't sold a single truck in two months, because the senior men took every customer who looked like money, and left her the ones they didn't want. She was going to be let go on Friday. And she'd been worrying about how to pay her rent in January. That commission was more than she'd made all year.""",
   "young woman alone at desk worried", "HER LAST WEEK")
sc("""The manager didn't let her go. He moved her to the desk by the front door. And he called a meeting the next morning, and he told every salesman in that building what happened, and he said, from now on, we greet every customer in the first two minutes. Every single one. I don't care what they're wearing. Helen says Brad lasted about three more months there, and then he moved on.""",
   "manager speaking to sales staff meeting", "EVERY CUSTOMER")

ch("Christmas morning")
sc("""Caleb came home on the twenty-second, sweetheart. And on Christmas morning, Helen walked him out to the driveway in his pajamas, and there was that dark blue truck with a big red bow on the hood. And on the dashboard, Helen had put the empty red coffee can, with Frank's note inside. Caleb read the note. And that big, strong Marine sat down on the tailgate and cried like a little boy.""",
   "blue truck with red bow in driveway Christmas", "FRANK'S NOTE")
sc("""And Maria came to Christmas dinner, honey. Helen invited her. Maria brought her mother's tamales, and Caleb drove them all to the beach in the new truck that evening, and they sat on the tailgate and ate sunflower seeds and watched the trucks go by. Maria's the top salesperson at that dealership now. And every year, on the fifteenth of December, she sends Helen a card. It says, thank you for seeing me too.""",
   "people sitting on truck tailgate at beach sunset", "SUNFLOWER SEEDS")

ch("Grandma's lesson")
sc("""Here's what I want you to remember, honey. Never judge someone by their clothes. The woman in the dirty garden pants might be carrying forty years of love in a coffee can. Tell me in the comments, sweetheart, have you ever been judged by how you looked? There are more of my family's stories in the playlist right there on your screen. Good night. Merry Christmas.""",
   "red coffee can on truck dashboard", "NEVER JUDGE BY CLOTHES")

for s in S:
    s["cuts"], s["moves"] = 4, True

